using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Xml;using BeamScheduleFormatter;
class ProfessionalTakeoffTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static BeamRow Row(string spacing){var row=new BeamRow{Mark="3B-1",Leg="2L",Diameter="O10",RevisedSpacing=spacing};for(int i=0;i<14;i++)row.Cells[i].Add("-");row.Cells[0][0]="300";row.Cells[1][0]="500";for(int i=2;i<8;i++)row.Cells[i][0]="2-O16";row.Cells[13][0]=spacing.Contains("FREE END")?"CANTILEVERED":"-";return row;}
 static BeamEstimate Ties(string spacing,double length){var result=new BeamEstimate();RevisedSchedule.AddTies(result,Row(spacing),"3B-1",length,new EstimateOptions(),null,null);return result;}
 static void Main(){var register=typeof(Encoding).GetMethod("RegisterProvider");bool has1252=true;try{System.Text.Encoding.GetEncoding(1252);}catch{has1252=false;}if(register!=null&&!has1252){var type=System.Reflection.Assembly.Load("System.Text.Encoding.CodePages").GetType("System.Text.CodePagesEncodingProvider");register.Invoke(null,new[]{type.GetProperty("Instance").GetValue(null,null)});}string a="1 - 50mm, REST AT 150mm TO FREE END";var shortBeam=Ties(a,.775);Check(shortBeam.Ties==6,"Screenshot short cantilever: six tie stations, including terminal closing station");Check(shortBeam.Notes.Any(n=>n.Contains("not mirrored")),"One-way cantilever interpretation is explicit");Check(Ties(a,.775).Ties==Ties("1 - 50mm, AND REST AT 150mm TO FREE END",.775).Ties,"Optional AND does not change spacing or quantity");Check(Ties("1 - 100mm, REST AT 150mm TO FREE END",.75).Ties==5,"Cantilever first tie uses the actual schedule offset");Check(Ties("1 - 50mm, 5 - 100mm, REST AT 200mm TO FREE END",3).Ties==18,"Cantilever dense zone is applied only at support");Check(Ties("1 - 50mm, 5 - 100mm, AND REST AT 200mm C/C",3).Ties==21,"Two-ended legacy dense zones remain unchanged");bool rejected=false;try{Ties("1 - 50mm, REST AT 0mm TO FREE END",1);}catch{rejected=true;}Check(rejected,"Zero rest spacing rejected");
 var p=new ProjectInformation{Name="CONVERGENCE AND SPECIAL SUPPORT PROGRAM — "+new string('W',200),Location="Aparri, Cagayan"};var source=Row(a);var entry=new EstimateInput{Beam="3B-1",Description="Playing Court — complete untruncated source description",Source=source,Length="0.775",Quantity="1",Support="Elevated",Result=EstimatorEngine.Calculate(source,"3B-1",.775,new EstimateOptions()),Measures=BeamQuantities.Calculate(300,500,.775,1,false,0)};var cfg=new LengthConfiguration{Name="Test",GradeSmall=40,GradeLarge=60,FySmall=275,FyLarge=420,Input=new LengthInput{Fc=21,Round=25,Simplified=true}};var plan=CommercialBars.Allocate(new[]{entry},cfg,new[]{6.0});var report=TakeoffEngineeringReports.Beams(p,new[]{entry},plan,"Detailed",true);var records=report.Sections.SelectMany(s=>s.Records).ToList();Check(records.Any(r=>r.Kind=="table"&&r.Rows.Any(row=>row.Any(v=>v.Contains(entry.Description)))),"Full beam description reaches structured table");Check(records.Any(r=>r.Kind=="table"&&r.Rows.Any(row=>row.Any(v=>v.Contains("TO FREE END")))),"Actual spacing retained in printed calculation basis");Check(records.Any(r=>r.Kind=="table"&&r.Headers.Contains("Purchase kg")),"Purchased steel has a real summary table");var layout=EngineeringQuantityPdf.Plan(report);Check(layout.DrawingPages.SelectMany(x=>x).Where(x=>x.Kind=="text").All(x=>x.Size>=7),"All report text meets 7pt minimum");EngineeringQuantityPdf.Write(Path.Combine(Path.GetTempPath(),"Professional-Beam-Sample.pdf"),report);
 var generic=ProfessionalReport.FromText("GRADE     DIA     NET kg     BUY kg\nG40       10      12.5       14.8\nG60       16      25.2       28.1", "Steel summary",p.Name,p.Location);var matrix=generic.Sections.SelectMany(s=>s.Records).Single(r=>r.Kind=="table");Check(matrix.Headers.Length==4&&matrix.Rows.Count==2&&matrix.Rows[1][3]=="28.1","Fixed-column legacy numeric data becomes a real table without losing values");
 var doc=new XmlDocument();doc.LoadXml("<ProgramOfWorks />");PowProjectInformation.Write(doc.DocumentElement,p);Check(PowProjectInformation.Read(doc.DocumentElement).Name==p.Name,"Whole POW stores full project title");Check(PowProjectInformation.Read(new XmlDocument().CreateElement("ProgramOfWorks"))==null,"Earlier POW files without project info stay compatible");Console.WriteLine("PASS: "+checks+" cantilever, professional report and whole-project metadata checks");}
}
